WITH unpacked AS (SELECT id, effective_from, tier_prices, discounts, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT *, LAG(entry_price, 2) OVER (ORDER BY avg_tier_price, id) AS prev_entry_price, FIRST_VALUE(entry_price, TRUE) OVER w_ordered AS first_known_entry_price, SUM(entry_price) OVER (PARTITION BY DATE_TRUNC('MONTH', effective_from) ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price FROM unpacked WINDOW w_ordered AS (PARTITION BY YEAR(effective_from) ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
